import * as fs from 'fs'
import * as path from 'path'

/**
 * Render `<opensaasDir>/procedures.ts`, the procedure builder bound to the
 * app's own `Context`.
 *
 * It imports the bundle's types and core's builder and nothing else: an
 * application's registry imports this file, and neither the config nor the
 * context factory is reached from it, so generation never loads a procedure.
 */
export function generateProcedures(): string {
  return `/**
 * Auto-generated procedure builder
 *
 * DO NOT EDIT - This file is automatically generated by 'pnpm generate'
 */

import { createProcedureBuilder } from '@opensaas/stack-core/procedures'
import type { Context } from './types.ts'

/**
 * Define a procedure typed to this application's context. Collect the
 * procedures in a registry module of your own and give it to a host such as
 * \`createProcedureHandler\` from \`@opensaas/stack-core/procedures\`.
 *
 * \`run\` opens no transaction. Wrap the writes that must succeed together in
 * \`context.transaction\`, and throw \`fail('<CODE>')\` for an outcome declared
 * in \`failures\`: a throw inside the transaction rolls it back.
 *
 * @example
 * \`\`\`typescript
 * import * as z from 'zod'
 * import { procedure } from '@/.opensaas/procedures'
 *
 * export const createPost = procedure({
 *   description: 'Create a draft post authored by the caller',
 *   input: z.object({ title: z.string().min(1) }),
 *   output: z.object({ id: z.string(), title: z.string() }),
 *   access: ({ session }) => session !== null,
 *   expose: ['web'],
 *   run: async ({ input, context }) => {
 *     const post = await context.db.Post.create({ data: { title: input.title } })
 *     if (post === null) throw new Error('Post was not created')
 *     return post
 *   },
 * })
 * \`\`\`
 */
export const procedure = createProcedureBuilder<Context>()
`
}

export function writeProcedures(outputPath: string): void {
  const dir = path.dirname(outputPath)
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true })
  }
  fs.writeFileSync(outputPath, generateProcedures(), 'utf-8')
}
